"use client";

import { useState } from "react";
import Link from "next/link";
import { ChevronDown, Heart, Menu, Search, ShoppingBag, X } from "lucide-react";
import { navLinks } from "../../data/home-data";
import { serif, wrap } from "../../lib/constants";
import { ThemeToggle } from "./theme-toggle";

const iconBtn =
  "flex h-9 w-9 items-center justify-center rounded-full text-white/85 transition hover:bg-white/15 hover:text-white";

/** Píldora flotante: se superpone al hero (el posicionamiento lo da la página). */
export function Header({ cartCount }: { cartCount: number }) {
  const [open, setOpen] = useState(false);

  return (
    <header className={`${wrap} pt-3`}>
      <div className="flex items-center justify-between gap-4 rounded-full border border-white/15 bg-black/35 py-2 pl-5 pr-2 text-white shadow-lg backdrop-blur-xl">
        <Link href="/" className="shrink-0 leading-none">
          <span
            className={`${serif} block text-2xl font-medium italic tracking-tight text-white`}
          >
            Zentrall
          </span>
          <span className="mt-1 hidden text-[7px] font-semibold uppercase tracking-[0.25em] text-white/60 lg:block">
            Compra · Descubre · Vive
          </span>
        </Link>

        <nav className="hidden items-center gap-1 text-xs font-medium xl:flex">
          {navLinks.map((link) => (
            <Link
              key={link.label}
              href={link.href}
              className={`flex items-center gap-1 rounded-full px-3.5 py-2 transition ${
                link.active
                  ? "bg-white/15 text-white"
                  : "text-white/70 hover:bg-white/10 hover:text-white"
              }`}
            >
              {link.label}
              {link.dropdown && <ChevronDown size={13} />}
            </Link>
          ))}
        </nav>

        <div className="flex items-center gap-1">
          <Link href="/explorar" aria-label="Buscar" className={iconBtn}>
            <Search size={18} />
          </Link>
          <Link
            href="/guardados"
            aria-label="Guardados"
            className={`${iconBtn} hidden sm:flex`}
          >
            <Heart size={18} />
          </Link>
          <Link
            href="/carrito"
            aria-label="Carrito"
            className={`${iconBtn} relative`}
          >
            <ShoppingBag size={18} />
            <span className="absolute right-0 top-0 flex h-4 min-w-4 items-center justify-center rounded-full bg-[var(--color-descuento)] px-1 text-[9px] font-bold text-white">
              {cartCount}
            </span>
          </Link>

          <ThemeToggle />

          <Link
            href="/login"
            className="ml-1 rounded-full bg-[var(--color-descuento)] px-5 py-2.5 text-xs font-bold text-white transition hover:opacity-90"
          >
            Entrar
          </Link>

          <button
            type="button"
            aria-label={open ? "Cerrar menú" : "Abrir menú"}
            onClick={() => setOpen((value) => !value)}
            className={`${iconBtn} xl:hidden`}
          >
            {open ? <X size={18} /> : <Menu size={18} />}
          </button>
        </div>
      </div>

      {open && (
        <div className="mt-2 flex flex-col gap-1 rounded-3xl border border-white/15 bg-black/60 p-3 text-white shadow-lg backdrop-blur-xl xl:hidden">
          {navLinks.map((link) => (
            <Link
              key={link.label}
              href={link.href}
              onClick={() => setOpen(false)}
              className="rounded-2xl px-4 py-3 text-sm font-medium text-white/90 transition hover:bg-white/10"
            >
              {link.label}
            </Link>
          ))}
        </div>
      )}
    </header>
  );
}