import { RotateCcw, Sparkles, Truck } from "lucide-react";
import { PROMO_CODE, wrap } from "../../lib/constants";

export function AnnouncementBar() {
  return (
    <div className="bg-[color-mix(in_srgb,var(--color-primario)_35%,#0d0c1d)] text-white">
      <div
        className={`${wrap} flex items-center justify-between gap-4 py-2 text-[11px] font-medium`}
      >
        <span className="flex items-center gap-2">
          <Truck size={14} /> Envío gratis en pedidos desde $75
        </span>
        <span className="hidden items-center gap-2 sm:flex">
          <Sparkles size={14} /> 15% de descuento en tu primer pedido · Código:{" "}
          {PROMO_CODE}
        </span>
        <span className="hidden items-center gap-2 md:flex">
          <RotateCcw size={14} /> Cambios fáciles en 30 días
        </span>
      </div>
    </div>
  );
}